 run("merged-class-clone",source,"class Foo { static field=11; static own(n:number): string { return 'method'; } } namespace Foo { export const merged = 1; } export = Foo;",[]string{"Head","Twin","Linked","Tail"})
 run("type-only-backlink","import { Renamed as Visible } from './lib';","class Thing {} export type { Thing as Renamed };",[]string{"Visible"})
}

